(function () {
  var RESIDENCY = 'Art Residency';
  var NUDE_MODEL = 'Nude model drawing';
  var NUDE_SLOT = '13;30 \u2013 16:00';
  var TUESDAY_SLOT = '18:30 \u2013 20:30';
  var SLOT_SELECTOR = 'input[name="time_slots"]';
  var attempts = 0;
  var bound = false;
  var dateHooked = false;

  function getDisableRules(program, workshop) {
    if (workshop === NUDE_MODEL) {
      return [
        function (date) {
          return date.getDay() !== 6;
        }
      ];
    }
    if (program !== RESIDENCY) {
      return [
        function (date) {
          return date.getDay() === 4;
        }
      ];
    }
    return [];
  }

  function isDateAllowed(date, program, workshop) {
    if (workshop === NUDE_MODEL) {
      return date.getDay() === 6;
    }
    if (program !== RESIDENCY && date.getDay() === 4) {
      return false;
    }
    return true;
  }

  function isSlotAllowed(value, workshop, selectedDate) {
    if (workshop === NUDE_MODEL) {
      return value === NUDE_SLOT;
    }
    if (value === TUESDAY_SLOT) {
      return !!(selectedDate && selectedDate.getDay() === 2);
    }
    return true;
  }

  function setSlotEnabled($input, allowed) {
    $input.prop('disabled', !allowed);
    $input.closest('label, .ff-el-form-check, .ff_item').css(
      allowed ? { opacity: '', pointerEvents: '' } : { opacity: 0.35, pointerEvents: 'none' }
    );
    if (!allowed && $input.is(':checked')) {
      $input.prop('checked', false).trigger('change');
    }
  }

  function applyTimeSlotRules(workshop, selectedDate) {
    $form.find(SLOT_SELECTOR).each(function () {
      setSlotEnabled($(this), isSlotAllowed($(this).val(), workshop, selectedDate));
    });
  }

  function hookDateChange(fp, workshopEl) {
    if (!fp || dateHooked) {
      return;
    }
    dateHooked = true;
    fp.config.onChange = (fp.config.onChange || []).concat([
      function (selectedDates) {
        var workshop = workshopEl ? workshopEl.value : '';
        applyTimeSlotRules(workshop, selectedDates[0] || null);
      }
    ]);
  }

  function applyRules() {
    var programEl = $form.find('select[name="dropdown"]')[0];
    var workshopEl = $form.find('select[name="dropdown_1"]')[0];
    var dateEl = $form.find('input[name="datetime"]')[0];
    var fp = dateEl && dateEl._flatpickr;
    var program;
    var workshop;
    var selected;

    if (!programEl) {
      return false;
    }

    program = programEl.value;
    workshop = workshopEl ? workshopEl.value : '';
    selected = fp && fp.selectedDates[0] ? fp.selectedDates[0] : null;

    if (fp) {
      fp.set('disable', getDisableRules(program, workshop));
      if (selected && !isDateAllowed(selected, program, workshop)) {
        fp.clear();
        selected = null;
      }
      hookDateChange(fp, workshopEl);
    }

    applyTimeSlotRules(workshop, selected);
    return true;
  }

  function bindListeners() {
    if (bound) {
      return;
    }
    bound = true;
    $form.find('select[name="dropdown"], select[name="dropdown_1"]').on('change', applyRules);
    $form.on('reInitExtras', function () {
      setTimeout(applyRules, 50);
    });
  }

  function tryInit() {
    if (applyRules()) {
      bindListeners();
      return;
    }
    if (++attempts < 40) {
      setTimeout(tryInit, 100);
    }
  }

  tryInit();
})();
